"""Development-only AYS read probe. No catalog writes or email sending."""
import json
from pathlib import Path
import sys
from urllib.parse import urlsplit

PROJECT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(PROJECT))

PROBE = r"""
const expectedOrigin = arguments[0];
const done = arguments[arguments.length - 1];
(async () => {
  if (location.origin !== expectedOrigin) return {error: "ORIGIN"};
  if (typeof window.g_ck !== "string" || !window.g_ck)
    return {error: "SESSION"};
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 15000);
  try {
    const response = await fetch(
      "/api/now/table/cmdb_ci_business_app?u_app_id=APP00005161&sysparm_fields=u_app_id,name,support_group,support_group.name,support_group.email&sysparm_limit=1&sysparm_display_value=all",
      {method: "GET", credentials: "same-origin", redirect: "error",
       cache: "no-store", signal: controller.signal,
       headers: {Accept: "application/json", "X-UserToken": window.g_ck}}
    );
    if (!response.ok) return {http: response.status};
    let body;
    try { body = await response.json(); }
    catch { return {http: response.status, error: "JSON"}; }
    if (!Array.isArray(body.result))
      return {http: response.status, error: "SHAPE"};
    const summary = {http: response.status, records: body.result.length};
    if (body.result.length !== 1) return summary;
    const record = body.result[0];
    const value = item => item && typeof item === "object" ? item.value : item;
    const present = item => typeof value(item) === "string" && value(item).trim().length > 0;
    summary.expected_id = value(record.u_app_id) === "APP00005161";
    if (!summary.expected_id) return summary;
    summary.name = present(record.name);
    summary.group = /^[0-9a-f]{32}$/i.test(value(record.support_group) || "");
    summary.group_name = present(record["support_group.name"]);
    summary.group_email = present(record["support_group.email"]);
    return summary;
  } catch (error) {
    return {error: controller.signal.aborted ? "TIMEOUT" : "REQUEST"};
  } finally {
    clearTimeout(timer);
  }
})().then(done, () => done({error: "REQUEST"}));
"""


def origin_only(text):
    text = text.strip()
    parts = urlsplit(text)
    if (parts.scheme != "https" or not parts.hostname or parts.username is not None
            or parts.password is not None or parts.path not in ("", "/")
            or parts.query or parts.fragment or any(c.isspace() for c in text)
            or "\\" in text):
        raise ValueError("Enter only the HTTPS AYS hostname")
    port = parts.port
    host = parts.hostname.encode("idna").decode("ascii").lower()
    return "https://" + host + (f":{port}" if port and port != 443 else "")


def browser_settings(project):
    source = project / "config" / "local_overrides.json"
    local = json.loads(source.read_text(encoding="utf-8-sig"))
    browser = local.get("browser", {})
    path = browser.get("driver_path")
    if (browser.get("driver_mode", "local") != "local"
            or not isinstance(path, str) or not Path(path).is_absolute()
            or not Path(path).is_file()):
        raise ValueError("Existing local EdgeDriver required")
    result = {"driver_mode": "local", "driver_path": path, "headless": False}
    binary = browser.get("binary_path")
    if binary:
        if not isinstance(binary, str) or not Path(binary).is_file():
            raise ValueError("Configured Edge binary missing")
        result["binary_path"] = binary
    return result


def report(summary):
    if not isinstance(summary, dict):
        print("PROBE: NO SUMMARY")
        return False
    errors = {"ORIGIN": "Return to AYS after SSO before continuing",
              "SESSION": "Session context unavailable on current page",
              "JSON": "Response was not JSON", "SHAPE": "Result array missing",
              "TIMEOUT": "Request timed out", "REQUEST": "Request failed or redirected"}
    if type(summary.get("http")) is int:
        print("HTTP:", summary["http"])
    if type(summary.get("records")) is int:
        print("RECORDS:", summary["records"])
    if "error" in summary:
        print("PROBE:", errors.get(summary["error"], "Unexpected response"))
    fields = {"expected_id": "EXPECTED ID", "name": "NAME PRESENT",
              "group": "GROUP REFERENCE", "group_name": "GROUP NAME PRESENT",
              "group_email": "GROUP EMAIL PRESENT"}
    for key, label in fields.items():
        if type(summary.get(key)) is bool:
            print(label + ":", "YES" if summary[key] else "NO")
    return (summary.get("http") == 200 and summary.get("records") == 1
            and all(summary.get(key) is True for key in fields) and "error" not in summary)


def main():
    driver = None
    phase = "settings"
    try:
        settings = browser_settings(PROJECT)
        import tkinter as tk
        from tkinter import simpledialog
        root = tk.Tk()
        root.withdraw()
        try:
            address = simpledialog.askstring(
                "AYS development probe", "Enter your AYS HTTPS base address only:", parent=root)
        finally:
            root.destroy()
        if not address:
            print("PROBE: CANCELLED")
            return 0
        phase = "address"
        origin = origin_only(address)
        from app_health_checker.browser.edge import create_edge
        phase = "browser launch"
        driver = create_edge(settings)
        driver.set_page_load_timeout(60)
        driver.set_script_timeout(25)
        phase = "open AYS"
        driver.get(origin + "/")
        print("Sign in normally in the NEW Edge window and open an AYS application record.")
        input("Then return here and press Enter to run the read-only probe: ")
        phase = "API probe"
        successful = report(driver.execute_async_script(PROBE, origin))
        print("PROBE:", "PASS" if successful else "INCOMPLETE")
        return 0 if successful else 1
    except KeyboardInterrupt:
        print("PROBE: CANCELLED")
        return 1
    except Exception:
        print("PROBE: STOPPED; phase=" + phase)
        return 1
    finally:
        if driver is not None:
            try:
                driver.quit()
            except Exception:
                print("BROWSER: Close the probe window manually")


if __name__ == "__main__":
    raise SystemExit(main())
